pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Reject impossible placements immediately
    if item_size > bin_residual {
        return f64::INFINITY;
    }

    let residual = post_residual as f64;
    let ratio = residual / bin_capacity as f64;

    // Base score: cubic residual penalty
    let mut score = ratio.powi(3) * 7.5;

    // Exponential penalty for large gaps, reward for tight gaps
    if ratio > 0.35 {
        score += (ratio - 0.35).powi(2) * 12.0;
    } else {
        score -= (0.35 - ratio).powi(2) * 4.0;
    }

    // New‑bin cost: cheaper early, more expensive later
    if bin_residual == bin_capacity {
        score += if open_bins_count < 4 { 2.0 } else { 5.0 };
    }

    // Compare to mean residual ratio of all open bins
    let mean_ratio = mean_residual / bin_capacity as f64;
    let diff_to_mean = (ratio - mean_ratio).abs();
    score += diff_to_mean * 2.0;

    // Fitting‑bins influence: prefer minimal residual among fitters
    if fitting_bins_count > 0 {
        score -= ratio.powi(2) * 3.0;
    } else {
        score += 4.0;
    }

    // Tighten packing near the stream’s end
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        if ratio < 0.08 {
            score -= 0.6;
        } else if ratio > 0.45 {
            score += 0.5;
        }
    }

    // Lookahead: prefer bins that can also accommodate the next item
    if residual >= next_item_size as f64 {
        score -= 0.5;
    } else {
        score += 0.3;
    }

    // Open‑bin count penalty / bonus
    if open_bins_count > 5 {
        score += (open_bins_count as f64 - 5.0) * 0.25;
    } else {
        score -= (5 - open_bins_count) as f64 * 0.04;
    }

    // Bonus for placing very large items (low residual)
    if item_size as f64 > 0.85 * bin_capacity as f64 {
        score -= 0.25;
    }

    // Additional penalties for moderate or large residuals
    if residual > 0.38 * bin_capacity as f64 {
        score += 0.35;
    } else if residual < 0.04 * bin_capacity as f64 {
        score -= 0.12;
    }

    // Target residual ratio incentive (≈10 % leftover)
    let target_ratio = 0.10;
    score -= (ratio - target_ratio).abs() * 5.0;

    score
}

